// src/engine/festivals.ts
/** Every date from `from` to `to`, both included (YYYY-MM-DD). */
function span(from, to) {
	const out = [];
	for (let d = parseISODate(from); toISODate(d) <= to; d = addDays(d, 1)) out.push(toISODate(d));
	return out;
}
